'use client';

import { useEffect, useState } from 'react';

/**
 * Prefer a nonce generated by the Server Component. Legacy call-sites that do
 * not yet provide one stay hydration-safe: both SSR and the first client render
 * see null, then a fresh browser nonce is generated after hydration. Callers
 * must not enable their command form until a nonce is returned.
 */
export function useResolvedCommandNonce(serverNonce?: string): string | null {
  const [clientNonce, setClientNonce] = useState<string | null>(null);

  useEffect(() => {
    if (!serverNonce && !clientNonce) {
      setClientNonce(crypto.randomUUID());
    }
  }, [serverNonce, clientNonce]);

  return serverNonce ?? clientNonce;
}
